class Book {
    String title;
    String author;

    Book(String bTitle, String bAuthor) {
        title = bTitle;
        author = bAuthor;
    }

    void printInfo() {
        System.out.println(title + " by " + author);
    }
}

public class Main {
    public static void main(String[] args) {
        Book b = new Book("Atomic Habits", "James Clear");
        b.printInfo();
    }
}

class Ticket {
    String movieName;
    String seatNumber;
    double price;

    Ticket(String movie, String seat, double p) {
        movieName = movie;
        seatNumber = seat;
        price = p;
    }
}

public class Main {
    public static void main(String[] args) {
        Ticket t1 = new Ticket("Inception", "A-12", 12.5);
        Ticket t2 = new Ticket("Interstellar", "B-05", 15.0);
        System.out.println("Ticket 1: " + t1.movieName + " [" + t1.seatNumber + "] - $" + t1.price);
        System.out.println("Ticket 2: " + t2.movieName + " [" + t2.seatNumber + "] - $" + t2.price);
    }
}

